24fa/1.5.starter:
(* Must have this exact header, and be tail recursive. *)
let rec mystery (f : int -> int) (x : int) : int =
  failwith "mystery: not written yet"

24fa/1.5.solution:
let rec mystery (f : int -> int) (x : int) : int =
  let rec loop (y : int) (acc : int) : int =
    if y = 0 then acc
    else loop (y - 1) ((f y) + acc)
  in loop x 0

