type 'a dqnode = {
  v : 'a;
  mutable next : 'a dqnode option;
  mutable prev : 'a dqnode option;
}
type 'a deque = {
  mutable head : 'a dqnode option;
  mutable tail : 'a dqnode option;
}

let create () : 'a deque = { head = None; tail = None }

let is_empty (d : 'a deque) : bool =
  begin match d.head with None -> true | Some _ -> false end

let insert_head (x : 'a) (d : 'a deque) : unit =
  let n = { v = x; next = d.head; prev = None } in
  (begin match d.head with None -> d.tail <- Some n | Some h -> h.prev <- Some n end);
  d.head <- Some n

let insert_tail (x : 'a) (d : 'a deque) : unit =
  let n = { v = x; next = None; prev = d.tail } in
  (begin match d.tail with None -> d.head <- Some n | Some t -> t.next <- Some n end);
  d.tail <- Some n

let remove_head (d : 'a deque) : 'a =
  begin match d.head with
  | None -> failwith "remove_head: empty deque"
  | Some n ->
    d.head <- n.next;
    (begin match n.next with None -> d.tail <- None | Some m -> m.prev <- None end);
    n.v
  end

let remove_tail (d : 'a deque) : 'a =
  begin match d.tail with
  | None -> failwith "remove_tail: empty deque"
  | Some n ->
    d.tail <- n.prev;
    (begin match n.prev with None -> d.head <- None | Some m -> m.next <- None end);
    n.v
  end

let from_list (l : 'a list) : 'a deque =
  let d = create () in
  List.iter (fun x -> insert_tail x d) l;
  d

(* Values from head to tail by next pointers. Gives up on a cycle. *)
let to_list (d : 'a deque) : 'a list =
  let rec loop (no : 'a dqnode option) (acc : 'a list) (steps : int) : 'a list =
    begin match no with
    | None -> List.rev acc
    | Some n ->
      if steps > 10_000_000 then failwith "to_list: the deque has a cycle"
      else loop n.next (n.v :: acc) (steps + 1)
    end in
  loop d.head [] 0

(* Values from tail to head by prev pointers. *)
let to_list_back (d : 'a deque) : 'a list =
  let rec loop (no : 'a dqnode option) (acc : 'a list) (steps : int) : 'a list =
    begin match no with
    | None -> List.rev acc
    | Some n ->
      if steps > 10_000_000 then failwith "to_list_back: the deque has a cycle"
      else loop n.prev (n.v :: acc) (steps + 1)
    end in
  loop d.tail [] 0

let nodes (d : 'a deque) : 'a dqnode list =
  let rec loop (no : 'a dqnode option) (acc : 'a dqnode list) (steps : int) : 'a dqnode list =
    begin match no with
    | None -> List.rev acc
    | Some n ->
      if steps > 10_000_000 then failwith "nodes: the deque has a cycle"
      else loop n.next (n :: acc) (steps + 1)
    end in
  loop d.head [] 0

let node_at (d : 'a deque) (i : int) : 'a dqnode = List.nth (nodes d) i

(* The deque invariant: (1), (2a)-(2f). *)
let valid (d : 'a deque) : bool =
  begin match d.head, d.tail with
  | None, None -> true
  | Some h, Some t ->
    (begin match h.prev with None -> true | Some _ -> false end) &&
    (let rec fwd (n : 'a dqnode) (steps : int) : bool =
       begin match n.next with
       | None -> n == t
       | Some m ->
         (begin match m.prev with Some p -> p == n | None -> false end)
         && steps < 10_000_000 && fwd m (steps + 1)
       end in
     fwd h 0)
  | _ -> false
  end

let show_ints (l : int list) : string = "[" ^ String.concat "; " (List.map string_of_int l) ^ "]"

let show_link (o : int dqnode option) : string =
  begin match o with None -> "None" | Some n -> "Some n" ^ string_of_int n.v end

(* Prints whether each clause of the deque invariant holds. *)
let report_deque (name : string) (d : 'a deque) : unit =
  let show (clause : string) (ok : bool) : unit =
    Printf.printf "%s %s: %s\n" name clause (if ok then "holds" else "BROKEN") in
  begin match d.head, d.tail with
  | None, None ->
    show "(1)" true;
    Printf.printf "%s is empty, so (2a)-(2f) do not apply\n" name
  | Some h, Some t ->
    show "(1)" true;
    let rec reach (no : 'a dqnode option) (target : 'a dqnode)
        (step : 'a dqnode -> 'a dqnode option) (steps : int) : bool =
      begin match no with
      | None -> false
      | Some n -> n == target || (steps < 1000 && reach (step n) target step (steps + 1))
      end in
    show "(2a)" (reach (Some h) t (fun n -> n.next) 0);
    show "(2b)" (begin match t.next with None -> true | Some _ -> false end);
    show "(2c)" (reach (Some t) h (fun n -> n.prev) 0);
    show "(2d)" (begin match h.prev with None -> true | Some _ -> false end);
    (* "Every node in the deque": reachable from head by next or from tail by prev. *)
    let rec collect (no : 'a dqnode option) (step : 'a dqnode -> 'a dqnode option)
        (seen : 'a dqnode list) : 'a dqnode list =
      begin match no with
      | None -> seen
      | Some n -> if List.memq n seen then seen else collect (step n) step (n :: seen)
      end in
    let all = collect (Some t) (fun n -> n.prev) (collect (Some h) (fun n -> n.next) []) in
    let points_back (n : 'a dqnode) (o : 'a dqnode option)
        (back : 'a dqnode -> 'a dqnode option) : bool =
      begin match o with
      | None -> true
      | Some m -> (begin match back m with Some p -> p == n | None -> false end)
      end in
    show "(2e)" (List.for_all (fun n -> points_back n n.next (fun m -> m.prev)) all);
    show "(2f)" (List.for_all (fun n -> points_back n n.prev (fun m -> m.next)) all)
  | _ ->
    show "(1)" false;
    Printf.printf "%s: head and tail disagree, so (2a)-(2f) do not apply\n" name
  end

