type 'a queue = { mutable head : 'a qnode option; mutable tail : 'a qnode option }

let create () : 'a queue = { head = None; tail = None }

let is_empty (q : 'a queue) : bool =
  begin match q.head with None -> true | Some _ -> false end

let enq (x : 'a) (q : 'a queue) : unit =
  let n = { v = x; next = None } in
  begin match q.tail with
  | None -> q.head <- Some n; q.tail <- Some n
  | Some t -> t.next <- Some n; q.tail <- Some n
  end

let deq (q : 'a queue) : 'a =
  begin match q.head with
  | None -> failwith "deq: empty queue"
  | Some n ->
    q.head <- n.next;
    (begin match n.next with None -> q.tail <- None | Some _ -> () end);
    n.v
  end

let from_list (l : 'a list) : 'a queue =
  let q = create () in
  List.iter (fun x -> enq x q) l;
  q

(* Values from head to tail. Gives up on a cycle. *)
let to_list (q : 'a queue) : 'a list =
  let rec loop (no : 'a qnode option) (acc : 'a list) (steps : int) : 'a list =
    begin match no with
    | None -> List.rev acc
    | Some n ->
      if steps > 10_000_000 then failwith "to_list: the queue has a cycle"
      else loop n.next (n.v :: acc) (steps + 1)
    end in
  loop q.head [] 0

(* The nodes from head to tail, to check which nodes were reused. *)
let nodes (q : 'a queue) : 'a qnode list =
  let rec loop (no : 'a qnode option) (acc : 'a qnode list) (steps : int) : 'a qnode list =
    begin match no with
    | None -> List.rev acc
    | Some n ->
      if steps > 10_000_000 then failwith "nodes: the queue has a cycle"
      else loop n.next (n :: acc) (steps + 1)
    end in
  loop q.head [] 0

let node_at (q : 'a queue) (i : int) : 'a qnode = List.nth (nodes q) i

let is_tail (q : 'a queue) (n : 'a qnode) : bool =
  begin match q.tail with Some t -> t == n | None -> false end

(* The queue invariant: (1) both None or both Some; (2a) tail reachable
   from head; (2b) tail.next = None. *)
let valid (q : 'a queue) : bool =
  begin match q.head, q.tail with
  | None, None -> true
  | Some _, Some t ->
    let rec reach (no : 'a qnode option) (steps : int) : bool =
      begin match no with
      | None -> false
      | Some n ->
        if n == t then (begin match n.next with None -> true | Some _ -> false end)
        else steps < 10_000_000 && reach n.next (steps + 1)
      end in
    reach q.head 0
  | _ -> false
  end

let show_ints (l : int list) : string = "[" ^ String.concat "; " (List.map string_of_int l) ^ "]"

(* Prints whether each clause of the queue invariant holds. *)
