  let show (clause : string) (ok : bool) : unit =
    Printf.printf "%s %s: %s\n" name clause (if ok then "holds" else "BROKEN") in
  begin match q.head, q.tail with
  | None, None ->
    show "(1)" true;
    Printf.printf "%s is empty, so (2a) and (2b) do not apply\n" name
  | Some h, Some t ->
    show "(1)" true;
    let rec reach (no : 'a qnode option) (steps : int) : bool =
      begin match no with
      | None -> false
      | Some n -> n == t || (steps < 1000 && reach n.next (steps + 1))
      end in
    show "(2a)" (reach (Some h) 0);
    show "(2b)" (begin match t.next with None -> true | Some _ -> false end)
  | _ ->
    show "(1)" false;
    Printf.printf "%s: head and tail disagree, so (2a) and (2b) do not apply\n" name
  end

