let count_exact (q : 'a queue) (pred : 'a -> bool) (count : int) : bool =
  let rec loop (curr : 'a qnode option) (seen : int) : bool =
    begin match curr with
    | None -> count = seen
    | Some node ->
      (seen <= count) &&
      (if pred node.v then loop node.next (seen + 1)
       else loop node.next seen)
    end in
  loop q.head 0

