  begin match d.head, d.tail with
  | None, None ->
    show "(1)" true;
    Printf.printf "%s is empty, so (2a)-(2f) do not apply\n" name
  | Some h, Some t ->
    show "(1)" true;
    let rec reach (no : 'a dqnode option) (target : 'a dqnode)
        (step : 'a dqnode -> 'a dqnode option) (steps : int) : bool =
